// The board drawn as a list.
//
// Same board, same groups, same drag. A column becomes a section of the list
// and a card becomes a row, and everything underneath - which group a heading
// is in, what order the rows are in, what a drag writes - is answered by the
// board's own model in kanban.ts rather than worked out again here. That is
// the whole point of it being a layout rather than a second board: a heading
// dragged into Done in the list is the same write as a card dropped in the
// Done column, and a board can be read either way round without either view
// knowing the other exists.
//
// Two things are the list's own. The **keyword comes first**, before the
// heading, because a todo list is read down that column - it is the thing the
// eye runs along, and a list that buries it among the other fields is a table
// that happens to contain tasks. And it is a **control** rather than a label:
// clicking it asks the server which keywords that heading's own file allows
// and offers those, the same picker the search table uses.
//
// The other fields are the board's to choose, named in kanban.ts so that the
// settings dialog and the table cannot disagree about what one is called.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Chip from '@mui/joy/Chip';
import Tooltip from '@mui/joy/Tooltip';
import IconButton from '@mui/joy/IconButton';
import Dropdown from '@mui/joy/Dropdown';
import Menu from '@mui/joy/Menu';
import MenuButton from '@mui/joy/MenuButton';
import MenuItem from '@mui/joy/MenuItem';
import CircularProgress from '@mui/joy/CircularProgress';

import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import DragIndicatorIcon from '@mui/icons-material/DragIndicator';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import KeyboardArrowUpIcon from '@mui/icons-material/KeyboardArrowUp';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff';
import VisibilityIcon from '@mui/icons-material/Visibility';

import { KanbanBoard, KanbanColumn, ODb } from '../db';
import {
    Card,
    ListField,
    listFieldsOf,
    listFieldText,
    swatch,
    autoSwatch,
    tint,
    columnTitle,
    columnValues,
    cardMatches,
    headerColorOf,
    headerValueOf,
    UNSET,
} from '../kanban';
import {
    dateLabel, isOverdue, isSetDate, baseName, PRIORITY_COLOR, CardDetail, CardAction,
} from './cardparts';
import { getStatusIcon, getStatusColor, getStatusCustomSx } from './statuslook';

// The headline's own column. Everything else is a fixed width; this one takes
// what is left, down to a floor that still fits a few words.
const NAME_MIN = 220;
// The rail on the left of every row: the grip, the fold arrow and the colour
// mark, at a fixed width so that everything below lines up down the whole list.
const RAIL = 52;
// The keyword's column, wide enough for the longest one anybody writes without
// leaving a gulf before the heading.
const STATUS_W = 138;

function rowTemplate(fields: ListField[]): string {
    const rest = fields.map(f => `${f.width}px`).join(' ');
    return `${RAIL}px ${STATUS_W}px minmax(${NAME_MIN}px, 1fr)${rest ? ' ' + rest : ''}`;
}

// A hairline that belongs to the page rather than boxing things in. Joy's
// divider at full strength reads as a grid; at half of it the eye follows the
// row without being told to.
const HAIRLINE = 'color-mix(in srgb, var(--joy-palette-divider) 55%, transparent)';

// --- one field of one row ---------------------------------------------------

function FieldCell({ card, field }: { card: Card; field: ListField }) {
    const text = listFieldText(card, field.key);

    if (field.key === 'priority') {
        if (!card.Priority) return <Muted />;
        const hue = PRIORITY_COLOR[card.Priority.toUpperCase()] || '#6b7280';
        return (
            <Tooltip size="sm" title={`Priority ${card.Priority.toUpperCase()}`}>
                <Box sx={{
                    width: 18, height: 18, borderRadius: '50%',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    fontSize: 10, fontWeight: 'lg', color: '#fff', background: hue,
                }}>
                    {card.Priority.toUpperCase()}
                </Box>
            </Tooltip>
        );
    }

    if (field.key === 'deadline' || field.key === 'scheduled') {
        const d = field.key === 'deadline' ? card.Deadline : card.Date;
        if (!isSetDate(d)) return <Muted />;
        const iso = d!.Start!;
        // A deadline that has gone by is the one thing in a list you want to
        // see without reading it, so it is the one thing given a colour.
        const late = field.key === 'deadline' && isOverdue(iso);
        return (
            <Typography
                level="body-xs"
                noWrap
                title={iso.substring(0, 10)}
                sx={{
                    color: late ? 'danger.softColor' : 'text.secondary',
                    fontWeight: late ? 'lg' : 'md',
                    ...(late ? {
                        background: 'var(--joy-palette-danger-softBg)',
                        borderRadius: 'sm', px: 0.75, py: '1px',
                    } : null),
                }}
            >
                {dateLabel(iso)}
            </Typography>
        );
    }

    if (field.key === 'tags') {
        const tags = card.Tags || [];
        if (tags.length === 0) return <Muted />;
        return (
            <Box sx={{ display: 'flex', gap: 0.375, minWidth: 0, overflow: 'hidden' }} title={tags.join(' ')}>
                {tags.map(t => (
                    <Chip
                        key={t}
                        size="sm"
                        variant="soft"
                        color="neutral"
                        sx={{ '--Chip-minHeight': '17px', fontSize: 10, px: 0.5, opacity: 0.85 }}
                    >
                        {t}
                    </Chip>
                ))}
            </Box>
        );
    }

    if (field.key === 'file') {
        return (
            <Typography level="body-xs" noWrap sx={{ color: 'text.tertiary' }} title={`${card.Filename}:${card.LineNum}`}>
                {baseName(card.Filename)}
            </Typography>
        );
    }

    if (text === '') return <Muted />;
    return (
        <Typography level="body-xs" noWrap sx={{ color: 'text.secondary' }} title={text}>
            {text}
        </Typography>
    );
}

// What a field with nothing in it looks like: a rule, faint enough to read as
// an empty cell rather than as a value somebody wrote.
function Muted() {
    return (
        <Box sx={{ width: 10, height: 1, background: 'var(--joy-palette-text-tertiary)', opacity: 0.35 }} />
    );
}

// --- the keyword ------------------------------------------------------------

// The keyword, as a control that opens where it is.
//
// It looks the same as the one in the search table - same icon, same colour -
// because it is the same thing, and a keyword drawn two ways is two things as
// far as the reader is concerned. What is different here is where the choices
// appear: under the chip that was clicked, not in the middle of the window.
// Changing a keyword is something you do to a row and then to the next row,
// and a dialog in the centre of the screen makes that a trip across the desk
// every time.
//
// What a heading may be set to is its own file's business - a file with its
// own `#+TODO:` line answers differently from the server's default - so the
// list asks rather than offering the board's columns. It asks when the menu is
// opened rather than while the list is being drawn: two hundred rows are two
// hundred requests nobody made.
function StatusCell({ card, onPick }: { card: Card; onPick: (status: string) => void }) {
    const [states, setStates] = React.useState<string[] | null>(null);
    const asked = React.useRef(false);

    const load = React.useCallback(() => {
        if (asked.current) return;
        asked.current = true;
        ODb.validStatus(card.Hash)
            .then(r => setStates([...(r.Active || []), ...(r.Done || [])]))
            .catch(() => setStates([]));
    }, [card.Hash]);

    // A heading whose keyword changed is a different heading as far as the
    // hash is concerned, so the answer is never stale - but a row reused for
    // another card would be, and this is what stops that.
    React.useEffect(() => {
        asked.current = false;
        setStates(null);
    }, [card.Hash]);

    const custom = getStatusCustomSx(card.Status);
    const chip = card.Status
        ? (
            <Chip
                size="sm"
                variant="soft"
                color={getStatusColor(card.Status)}
                startDecorator={getStatusIcon(card.Status)}
                sx={{
                    '--Chip-minHeight': '22px', fontSize: 11, fontWeight: 'lg',
                    maxWidth: '100%', justifyContent: 'flex-start', pointerEvents: 'none',
                    '& .MuiSvgIcon-root': { fontSize: 13 },
                    ...(custom || {}),
                }}
            >
                {card.Status}
            </Chip>
        )
        : (
            <Chip
                size="sm"
                variant="outlined"
                color="neutral"
                sx={{
                    '--Chip-minHeight': '22px', fontSize: 11, borderStyle: 'dashed',
                    color: 'text.tertiary', justifyContent: 'flex-start', minWidth: 78,
                    pointerEvents: 'none',
                }}
            >
                none
            </Chip>
        );

    return (
        <Dropdown onOpenChange={(_, open) => { if (open) load(); }}>
            <Tooltip
                size="sm"
                enterDelay={400}
                title={card.Status ? `${card.Status} — click to change the keyword` : 'No keyword — click to give this heading one'}
            >
                {/* A real button around the chip rather than a clickable chip:
                    the chip is the picture, the button is the control, and
                    nesting them the other way round puts a button inside a
                    button. The click stops here so that the row does not also
                    open underneath the menu. */}
                <MenuButton
                    variant="plain"
                    color="neutral"
                    onClick={e => e.stopPropagation()}
                    sx={{
                        p: 0, minHeight: 0, minWidth: 0, border: 0, borderRadius: 'sm',
                        background: 'transparent', maxWidth: '100%',
                        '&:hover': { background: 'transparent' },
                        '&:focus-visible': { outlineOffset: 2 },
                    }}
                >
                    {chip}
                </MenuButton>
            </Tooltip>
            <Menu
                size="sm"
                placement="bottom-start"
                onClick={e => e.stopPropagation()}
                sx={{ minWidth: 190, py: 0.5 }}
            >
                {states === null ? (
                    <MenuItem disabled>
                        <CircularProgress size="sm" />
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            Asking that file what it allows…
                        </Typography>
                    </MenuItem>
                ) : states.length === 0 ? (
                    <MenuItem disabled>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            That file names no todo keywords.
                        </Typography>
                    </MenuItem>
                ) : states.map(sname => (
                    <MenuItem
                        key={sname}
                        selected={sname === card.Status}
                        onClick={() => { if (sname !== card.Status) onPick(sname); }}
                    >
                        <Chip
                            size="sm"
                            variant={sname === card.Status ? 'solid' : 'soft'}
                            color={getStatusColor(sname)}
                            startDecorator={getStatusIcon(sname)}
                            sx={{
                                '--Chip-minHeight': '20px', fontSize: 11, fontWeight: 'lg',
                                pointerEvents: 'none',
                                '& .MuiSvgIcon-root': { fontSize: 13 },
                                ...(sname === card.Status ? {} : (getStatusCustomSx(sname) || {})),
                            }}
                        >
                            {sname}
                        </Chip>
                    </MenuItem>
                ))}
            </Menu>
        </Dropdown>
    );
}

// --- one row ----------------------------------------------------------------

// Which side of a row the pointer is on - above it or below it.
function halfOf(e: React.DragEvent): 'top' | 'bottom' {
    const r = (e.currentTarget as HTMLElement).getBoundingClientRect();
    return e.clientY < r.top + r.height / 2 ? 'top' : 'bottom';
}

function Row({
    card, board, fields, template, dark, open, dim, dragging, clocked, showLine, done,
    onOpen, onPickStatus, onDragStart, onDragEnd, onDragOverRow, onDropRow, onAct,
}: {
    card: Card;
    board: KanbanBoard;
    fields: ListField[];
    template: string;
    dark: boolean;
    open: boolean;
    dim: boolean;
    dragging: boolean;
    clocked: boolean;
    showLine: boolean;
    done: boolean;
    onOpen: () => void;
    onPickStatus: (status: string) => void;
    onDragStart: () => void;
    onDragEnd: () => void;
    onDragOverRow: (half: 'top' | 'bottom') => void;
    onDropRow: (half: 'top' | 'bottom') => void;
    onAct: (what: CardAction, card: Card) => void;
}) {
    const mark = headerColorOf(card, board, dark);
    const markValue = headerValueOf(card, board);

    return (
        <Box
            onDragOver={e => { e.preventDefault(); e.stopPropagation(); onDragOverRow(halfOf(e)); }}
            // The drop says where it landed rather than trusting the last
            // dragover to have been this row's. They are two different events
            // and the pointer can leave a row between them - which lands the
            // moved row at the end of the section, quietly, every time.
            onDrop={e => { e.preventDefault(); e.stopPropagation(); onDropRow(halfOf(e)); }}
            sx={{ position: 'relative', opacity: dragging ? 0.3 : dim ? 0.35 : 1, transition: 'opacity 0.15s' }}
        >
            {showLine && (
                <Box sx={{
                    position: 'absolute', left: RAIL - 8, right: 12, top: -1, height: 2,
                    background: 'var(--joy-palette-primary-solidBg)', borderRadius: 2, zIndex: 2,
                    '&::before': {
                        content: '""', position: 'absolute', left: -4, top: -3,
                        width: 8, height: 8, borderRadius: '50%',
                        background: 'var(--joy-palette-primary-solidBg)',
                    },
                }} />
            )}
            <Box
                // The whole row is the handle. A grip that only works on its own
                // few pixels is the difference between reordering a list and
                // fighting it, and the row has nothing else a press could mean.
                draggable
                onDragStart={onDragStart}
                onDragEnd={onDragEnd}
                onClick={onOpen}
                sx={{
                    display: 'grid',
                    gridTemplateColumns: template,
                    alignItems: 'center',
                    gap: 1.25,
                    minHeight: 38,
                    pr: 1.5,
                    cursor: 'grab',
                    borderBottom: '1px solid',
                    borderColor: HAIRLINE,
                    transition: 'background 0.12s',
                    '&:hover': { background: 'var(--joy-palette-background-level1)' },
                    '&:hover .kl-grip': { opacity: 0.55 },
                    '&:active': { cursor: 'grabbing' },
                }}
            >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.125, pl: 0.25 }}>
                    <DragIndicatorIcon
                        className="kl-grip"
                        sx={{ fontSize: 14, color: 'text.tertiary', opacity: 0, transition: 'opacity 0.15s' }}
                    />
                    {open
                        ? <ExpandMoreIcon sx={{ fontSize: 16, color: 'text.tertiary' }} />
                        : <ChevronRightIcon sx={{ fontSize: 16, color: 'text.tertiary', opacity: 0.6 }} />}
                    <Tooltip
                        size="sm"
                        title={markValue ? `${(board.headerKey || 'COLOUR').toUpperCase()}: ${markValue}` : ''}
                    >
                        <Box sx={{ width: 3, height: 20, borderRadius: 2, background: mark, flexShrink: 0, ml: 0.5 }} />
                    </Tooltip>
                </Box>

                <Box sx={{ minWidth: 0, display: 'flex' }}>
                    <StatusCell card={card} onPick={onPickStatus} />
                </Box>

                <Typography
                    level="body-sm"
                    noWrap
                    sx={{
                        minWidth: 0,
                        fontWeight: open ? 'lg' : 'md',
                        // A finished heading is still worth seeing and no longer
                        // worth reading, which is what a struck-through grey is.
                        textDecoration: done ? 'line-through' : 'none',
                        color: done ? 'text.tertiary' : 'text.primary',
                    }}
                    title={card.Headline}
                >
                    {card.Headline}
                </Typography>

                {fields.map(f => (
                    <Box key={f.key} sx={{
                        minWidth: 0, overflow: 'hidden',
                        display: 'flex', alignItems: 'center',
                        justifyContent: f.right ? 'flex-end' : 'flex-start',
                    }}>
                        <FieldCell card={card} field={f} />
                    </Box>
                ))}
            </Box>

            {open && (
                <Box
                    // Not draggable, and clicks stay here: the detail is full of
                    // things to press, and a row that folded shut under every
                    // one of them would be unusable.
                    onClick={e => e.stopPropagation()}
                    sx={{
                        display: 'flex', my: 0.75, px: 2, py: 1.25,
                        borderRadius: 'sm', borderLeft: '3px solid', borderLeftColor: mark,
                        background: 'var(--joy-palette-background-level1)',
                        maxHeight: 340,
                        // A table wider than the window scrolls sideways, and a
                        // detail panel as wide as the table puts its own buttons
                        // off the right of the screen. It is pinned to the left
                        // edge instead and given a readable measure, so opening
                        // a row never means scrolling to find what opened.
                        position: 'sticky', left: RAIL, ml: `${RAIL}px`, mr: 1.5,
                        width: 'min(820px, 100%)', maxWidth: 820,
                    }}
                >
                    <CardDetail card={card} board={board} clocked={clocked} onAct={onAct} />
                </Box>
            )}
        </Box>
    );
}

// --- one section ------------------------------------------------------------

function Group({
    col, cards, board, fields, template, dark, opened, terms, draggingHash, dropIndex,
    isDropTarget, dropRefused, clockedHash, doneStates, canUp, canDown,
    onCollapse, onOpen, onPickStatus, onMove, onHide, onDragStart, onDragEnd, onDragOverAt, onDrop, onAct,
}: {
    col: KanbanColumn;
    cards: Card[];
    board: KanbanBoard;
    fields: ListField[];
    template: string;
    dark: boolean;
    opened: Set<string>;
    terms: string[];
    draggingHash: string | null;
    dropIndex: number | null;
    isDropTarget: boolean;
    dropRefused: boolean;
    clockedHash: string;
    doneStates: Set<string>;
    canUp: boolean;
    canDown: boolean;
    onCollapse: (value: string, collapsed: boolean) => void;
    onOpen: (hash: string) => void;
    onPickStatus: (card: Card, status: string) => void;
    onMove: (value: string, by: number) => void;
    onHide: (value: string) => void;
    onDragStart: (card: Card) => void;
    onDragEnd: () => void;
    onDragOverAt: (value: string, index: number) => void;
    onDrop: (value: string, index?: number) => void;
    onAct: (what: CardAction, card: Card) => void;
}) {
    const sw = col.color ? swatch(col.color) : autoSwatch(col.value || 'unset');
    const title = columnTitle(col) || 'Untitled';
    const over = col.limit > 0 && cards.length > col.limit;
    const values = columnValues(col);
    const line = isDropTarget && !dropRefused ? dropIndex : null;

    const arrow = (up: boolean) => (
        <Tooltip size="sm" title={up ? 'Move this section up' : 'Move this section down'}>
            <span>
                <IconButton
                    size="sm"
                    variant="plain"
                    color="neutral"
                    disabled={up ? !canUp : !canDown}
                    onClick={e => { e.stopPropagation(); onMove(col.value, up ? -1 : 1); }}
                    sx={{ '--IconButton-size': '22px', minWidth: 22 }}
                >
                    {up ? <KeyboardArrowUpIcon sx={{ fontSize: 16 }} /> : <KeyboardArrowDownIcon sx={{ fontSize: 16 }} />}
                </IconButton>
            </span>
        </Tooltip>
    );

    return (
        <Box
            onDragOver={e => { e.preventDefault(); onDragOverAt(col.value, cards.length); }}
            onDrop={e => { e.preventDefault(); onDrop(col.value, cards.length); }}
            sx={{ mb: 2 }}
        >
            {/* The section heading. Dropping on it means the end of the section,
                which is what dragging a task onto a section name means
                everywhere else it is offered. */}
            <Box
                onClick={() => onCollapse(col.value, !col.collapsed)}
                sx={{
                    display: 'flex', alignItems: 'center', gap: 1, pl: 1.25, pr: 1.5, py: 0.875,
                    position: 'sticky', top: 0, zIndex: 3, cursor: 'pointer',
                    background: isDropTarget && !dropRefused
                        ? tint(sw.hex, 0.18)
                        : 'var(--joy-palette-background-surface)',
                    backdropFilter: 'blur(6px)',
                    borderBottom: '1px solid', borderColor: HAIRLINE,
                    transition: 'background 0.15s',
                    '&:hover .kl-move': { opacity: 1 },
                }}
            >
                {/* The section's colour, as a bar rather than a dot: it lines the
                    rows up under their own heading down a long list. */}
                <Box sx={{ width: 3, height: 16, borderRadius: 2, background: sw.hex, flexShrink: 0 }} />
                {col.collapsed
                    ? <ChevronRightIcon sx={{ fontSize: 17, color: 'text.tertiary' }} />
                    : <ExpandMoreIcon sx={{ fontSize: 17, color: 'text.tertiary' }} />}
                <Typography
                    level="body-xs"
                    noWrap
                    sx={{
                        minWidth: 0, fontWeight: 'xl', letterSpacing: '0.06em',
                        textTransform: 'uppercase', color: 'text.primary',
                    }}
                    title={col.value || title}
                >
                    {title}
                </Typography>
                <Tooltip size="sm" title={col.limit > 0 ? `${cards.length} of at most ${col.limit}` : `${cards.length} rows`}>
                    <Chip
                        size="sm"
                        variant={over ? 'solid' : 'soft'}
                        color={over ? 'danger' : 'neutral'}
                        sx={{ '--Chip-minHeight': '17px', fontSize: 10, px: 0.625, opacity: over ? 1 : 0.8 }}
                    >
                        {col.limit > 0 ? `${cards.length}/${col.limit}` : cards.length}
                    </Chip>
                </Tooltip>

                {/* While a row is in the air, a section that answers to more than
                    one spelling offers one square per spelling - the same as the
                    board's columns do, and for the same reason: the section is
                    one place, but dropping still writes one particular value. */}
                {draggingHash !== null && values.length > 1 && (
                    <Box sx={{ display: 'flex', gap: 0.5, ml: 1 }} onClick={e => e.stopPropagation()}>
                        {values.map(v => (
                            <Box
                                key={v}
                                onDragOver={e => { e.preventDefault(); e.stopPropagation(); onDragOverAt(col.value, cards.length); }}
                                onDrop={e => { e.preventDefault(); e.stopPropagation(); onDrop(v, cards.length); }}
                                sx={{
                                    px: 0.75, py: 0.25, borderRadius: 'sm', border: '1px dashed',
                                    borderColor: sw.hex, background: tint(sw.hex, 0.10),
                                    cursor: 'copy', '&:hover': { background: tint(sw.hex, 0.28) },
                                }}
                            >
                                <Typography level="body-xs" noWrap sx={{ fontWeight: 'lg' }}>{v}</Typography>
                            </Box>
                        ))}
                    </Box>
                )}

                {dropRefused && isDropTarget && (
                    <Typography level="body-xs" sx={{ color: 'danger.softColor', ml: 1 }}>
                        Cannot drop here
                    </Typography>
                )}

                <Box
                    className="kl-move"
                    sx={{ ml: 'auto', display: 'flex', gap: 0.25, opacity: 0, transition: 'opacity 0.15s' }}
                >
                    {arrow(true)}
                    {arrow(false)}
                    {/* Putting a section away is not the same as folding it.
                        Folded still says how many are in there; hidden is for
                        the sections this board is not about today, and the
                        only way back is the toolbar - which is why the count
                        goes in the tooltip, so nothing is put away without
                        being told what is going with it. */}
                    <Tooltip
                        size="sm"
                        title={cards.length > 0
                            ? `Hide this section and its ${cards.length} row${cards.length === 1 ? '' : 's'}`
                            : 'Hide this section'}
                    >
                        <IconButton
                            size="sm"
                            variant="plain"
                            color="neutral"
                            aria-label={`Hide the ${title} section`}
                            onClick={e => { e.stopPropagation(); onHide(col.value); }}
                            sx={{ '--IconButton-size': '22px', minWidth: 22 }}
                        >
                            <VisibilityOffIcon sx={{ fontSize: 15 }} />
                        </IconButton>
                    </Tooltip>
                </Box>
            </Box>

            {!col.collapsed && cards.length === 0 && (
                <Box sx={{ pl: `${RAIL}px`, py: 1.25, borderBottom: '1px solid', borderColor: HAIRLINE }}>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>
                        {draggingHash ? 'Drop here' : 'Nothing here'}
                    </Typography>
                </Box>
            )}

            {!col.collapsed && cards.map((c, i) => (
                <Row
                    key={c.Hash}
                    card={c}
                    board={board}
                    fields={fields}
                    template={template}
                    dark={dark}
                    open={opened.has(c.Hash)}
                    dim={terms.length > 0 && !cardMatches(c, terms)}
                    dragging={draggingHash === c.Hash}
                    clocked={clockedHash === c.Hash}
                    showLine={line === i}
                    done={doneStates.has(c.Status)}
                    onOpen={() => onOpen(c.Hash)}
                    onPickStatus={status => onPickStatus(c, status)}
                    onDragStart={() => onDragStart(c)}
                    onDragEnd={onDragEnd}
                    onDragOverRow={half => onDragOverAt(col.value, half === 'top' ? i : i + 1)}
                    onDropRow={half => onDrop(col.value, half === 'top' ? i : i + 1)}
                    onAct={onAct}
                />
            ))}

            {!col.collapsed && line === cards.length && cards.length > 0 && (
                <Box sx={{
                    height: 2, ml: `${RAIL - 8}px`, mr: 1.5, borderRadius: 2,
                    background: 'var(--joy-palette-primary-solidBg)',
                }} />
            )}
        </Box>
    );
}

// --- the list ---------------------------------------------------------------

export default function KanbanList(props: {
    board: KanbanBoard;
    // The sections on show. Hidden ones are already gone from this.
    columns: KanbanColumn[];
    // Every section the board has, hidden ones included, so the restore menu
    // can name what is missing and put it back where it belongs.
    allColumns: KanbanColumn[];
    buckets: Map<string, Card[]>;
    terms: string[];
    dark: boolean;
    doneStates: string[];
    draggingHash: string | null;
    dropAt: { col: string; index: number } | null;
    clockedHash: string;
    dropRefusedFor: (value: string) => boolean;
    onCollapse: (value: string, collapsed: boolean) => void;
    onMoveSection: (value: string, by: number) => void;
    onHideSection: (value: string, hidden: boolean) => void;
    onSetStatus: (card: Card, status: string) => void;
    onDragStart: (card: Card) => void;
    onDragEnd: () => void;
    onDragOverAt: (value: string, index: number) => void;
    onDrop: (value: string, index?: number) => void;
    onAct: (what: CardAction, card: Card) => void;
    onSort: (sort: KanbanBoard['sort']) => void;
}) {
    const { board, columns, buckets, terms, dark, draggingHash, dropAt, clockedHash } = props;

    // Which rows are open. The list's own, not the board's: what you were
    // reading is not a property of the plan.
    const [opened, setOpened] = React.useState<Set<string>>(new Set());
    const toggleOpen = React.useCallback((hash: string) => {
        setOpened(prev => {
            const next = new Set(prev);
            if (next.has(hash)) next.delete(hash); else next.add(hash);
            return next;
        });
    }, []);

    // The keyword has a column of its own at the front, so it is never also one
    // of the fields - a board saved with it among them would otherwise show it
    // twice.
    const fields = React.useMemo(
        () => listFieldsOf(board).filter(f => f.key !== 'status'),
        [board],
    );
    const template = React.useMemo(() => rowTemplate(fields), [fields]);
    const doneStates = React.useMemo(() => new Set(props.doneStates), [props.doneStates]);

    // The catch-all section is appended rather than stored and always sits
    // first, so it is not one of the ones that can be moved.
    const movable = React.useMemo(
        () => columns.filter(c => c.value !== UNSET).map(c => c.value),
        [columns],
    );

    // A heading in the table is the board's sort, said where the sort can be
    // seen and changed - which is the one thing a list view is expected to do
    // that a board is not. Dragging still works: it writes an order and puts
    // the board back on manual.
    const sortBy = (f: ListField) => {
        if (!f.sort) return;
        props.onSort(board.sort === f.sort ? 'manual' : f.sort);
    };

    const headCell = (label: string, f?: ListField) => (
        <Box
            key={f ? f.key : label}
            onClick={() => f && sortBy(f)}
            sx={{
                display: 'flex', alignItems: 'center', gap: 0.25, minWidth: 0,
                justifyContent: f && f.right ? 'flex-end' : 'flex-start',
                cursor: f && f.sort ? 'pointer' : 'default',
                '&:hover': f && f.sort ? { '& .kl-h': { color: 'text.primary' } } : undefined,
            }}
        >
            <Typography
                className="kl-h"
                level="body-xs"
                noWrap
                sx={{
                    fontWeight: 'lg', letterSpacing: '0.07em', textTransform: 'uppercase',
                    fontSize: 10, color: 'text.tertiary', transition: 'color 0.12s',
                }}
                title={f && f.sort ? `Sort by ${label.toLowerCase()}` : label}
            >
                {label}
            </Typography>
            {f && f.sort && board.sort === f.sort && (
                <ArrowUpwardIcon sx={{ fontSize: 11, color: 'text.secondary' }} />
            )}
        </Box>
    );

    // Sections put away, in the order the board draws them rather than the
    // order they were hidden in - the menu is a picture of the board with the
    // gaps in it, and a list that reordered itself as things were put away
    // would not be.
    const away = React.useMemo(() => {
        const set = new Set(board.hidden || []);
        return props.allColumns.filter(c => set.has(c.value));
    }, [board.hidden, props.allColumns]);

    return (
        <>
            {away.length > 0 && (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                    <Dropdown>
                        <MenuButton
                            size="sm"
                            variant="soft"
                            color="neutral"
                            startDecorator={<VisibilityOffIcon sx={{ fontSize: 16 }} />}
                        >
                            {away.length} hidden
                        </MenuButton>
                        <Menu size="sm" placement="bottom-start" sx={{ minWidth: 220 }}>
                            {away.map(c => {
                                const sw = c.color ? swatch(c.color) : autoSwatch(c.value || 'unset');
                                const n = (buckets.get(c.value) || []).length;
                                return (
                                    <MenuItem key={c.value || ' unset'} onClick={() => props.onHideSection(c.value, false)}>
                                        <Box sx={{ width: 3, height: 14, borderRadius: 2, background: sw.hex, flexShrink: 0 }} />
                                        <Typography level="body-sm" sx={{ flex: 1, minWidth: 0 }} noWrap>
                                            {columnTitle(c) || 'Untitled'}
                                        </Typography>
                                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{n}</Typography>
                                        <VisibilityIcon sx={{ fontSize: 15, color: 'text.tertiary' }} />
                                    </MenuItem>
                                );
                            })}
                            <MenuItem
                                onClick={() => away.forEach(c => props.onHideSection(c.value, false))}
                                sx={{ borderTop: '1px solid', borderColor: 'divider' }}
                            >
                                <Typography level="body-sm" sx={{ fontWeight: 'lg' }}>Show them all</Typography>
                            </MenuItem>
                        </Menu>
                    </Dropdown>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        {away.map(c => columnTitle(c) || 'Untitled').join(', ')}
                    </Typography>
                </Box>
            )}
            <Sheet
                variant="outlined"
                sx={{
                    borderRadius: 'md', flex: 1, minHeight: 0, overflow: 'auto',
                    borderColor: HAIRLINE, boxShadow: 'xs',
                }}
            >
                <Box sx={{ minWidth: 'fit-content' }}>
                    {/* The table's own heading row, over the sticky section
                        headings, so scrolling never leaves the fields unnamed. */}
                    <Box sx={{
                        display: 'grid', gridTemplateColumns: template,
                        gap: 1.25, alignItems: 'center',
                        pr: 1.5, py: 1, position: 'sticky', top: 0, zIndex: 4,
                        background: 'var(--joy-palette-background-level1)',
                        borderBottom: '1px solid', borderColor: HAIRLINE,
                    }}>
                        {/* The rail's own cell, never labelled: it holds the
                            grip, not a field. Present so that the header uses
                            the rows' template and the columns cannot drift
                            apart by a gap's width. */}
                        <Box />
                        {headCell('Keyword')}
                        {headCell('Heading')}
                        {fields.map(f => headCell(f.label, f))}
                    </Box>

                    <Box sx={{ px: 0.5, pt: 0.5 }}>
                        {columns.map(col => (
                            <Group
                                key={col.value || ' unset'}
                                col={col}
                                cards={buckets.get(col.value) || []}
                                board={board}
                                fields={fields}
                                template={template}
                                dark={dark}
                                opened={opened}
                                terms={terms}
                                draggingHash={draggingHash}
                                dropIndex={dropAt && dropAt.col === col.value ? dropAt.index : null}
                                isDropTarget={draggingHash !== null && !!dropAt && dropAt.col === col.value}
                                dropRefused={props.dropRefusedFor(col.value)}
                                clockedHash={clockedHash}
                                doneStates={doneStates}
                                canUp={movable.indexOf(col.value) > 0}
                                canDown={movable.indexOf(col.value) >= 0 && movable.indexOf(col.value) < movable.length - 1}
                                onCollapse={props.onCollapse}
                                onOpen={toggleOpen}
                                onPickStatus={props.onSetStatus}
                                onMove={props.onMoveSection}
                                onHide={v => props.onHideSection(v, true)}
                                onDragStart={props.onDragStart}
                                onDragEnd={props.onDragEnd}
                                onDragOverAt={props.onDragOverAt}
                                onDrop={props.onDrop}
                                onAct={props.onAct}
                            />
                        ))}
                        {columns.length === 0 && (
                            <Typography level="body-sm" sx={{ color: 'text.tertiary', p: 3 }}>
                                Nothing to show until this board has a group.
                            </Typography>
                        )}
                    </Box>
                </Box>
            </Sheet>

        </>
    );
}
